		return Version{}, ErrNotFound
	case err != nil:
		return Version{}, fmt.Errorf("load source: %w", err)
	}

	items, err := loadItems(ctx, conn, namespace, environment, sourceVersion)
	if err != nil {
		return Version{}, err
